{
  "学校名称": "初星学院",
  "学制": "初中、高中、大学一体化",
  "特色": "偶像培养与制作人培养并重",
  "专业设置": {
    "普通专业": "与正常大学相同",
    "特色专业": {
      "偶像科": {
        "学段": ["初中", "高中"],
        "课程设置": [
          "舞蹈课",
          "声乐课",
          "形象课",
          "必要的理论课（减少学习量）"
        ],
        "考核方式": "每学期末进行偶像能力测试"
      },
      "制作人科": {
        "学段": ["大学"],
        "主要任务": "引导和培养偶像科学生",
        "职责": [
          "与选中的偶像科学生签订担当契约",
          "以亦师亦友的身份陪伴偶像科学生",
          "为偶像科学生提供指导和建议"
        ]
      }
    }
  },
  "偶像科与制作人科关系": {
    "正式关系": "搭档、朋友",
    "潜在发展": "长期搭档，可能发展为恋人关系"
  },
  "教学特色": {
    "偶像科": "注重实践，减少理论课程",
    "制作人科": "理论与实践并重，重点培养管理和引导能力"
  },
  "学校氛围": "充满活力、竞争与合作并存",
  "隐藏设定": "制作人科学生与偶像科学生往往会长期合作，不乏最终成为恋人的案例"
}

